using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Reflection;
using System.Web.Script.Serialization;

namespace AABattle {
 // 트레이너 자질(지시·통솔·육성) 등급에 따른 권한과 보정
 public static class TrainerAccessRules {
  public const string AimOrders="order.aim",SureHitOrder="order.sure-hit",Pt1="potential.pt1",Pt2="potential.pt2";
  public static readonly string[] UnlockNames={AimOrders,SureHitOrder,Pt1,Pt2};
  static readonly string[] RankBands={"E","D","C","B","A","AA","AAA","S"};
  static string Band(string rank){return new string((rank??"").ToUpperInvariant().Where(x=>x>='A'&&x<='Z').ToArray());}
  static int RankIndex(string rank){return Array.IndexOf(RankBands,Band(rank));}
  static AptitudeRecord Aptitude(TrainerRecord trainer,string name){if(trainer==null)return null;return name=="지시"?trainer.command:name=="육성"?trainer.training:name=="통솔"?trainer.leadership:trainer.ability;}
  public static bool RankAtLeast(string actual,string required){int a=RankIndex(actual),r=RankIndex(required);return a>=0&&r>=0&&a>=r;}
  public static bool TrainerAtLeast(TrainerRecord trainer,string aptitude,string required,TrainerBattleState state=null){var value=Aptitude(trainer,aptitude);return value!=null&&RankAtLeast(RoleModules.AdjustedRank(value.rank,aptitude,state),required);}
  // 『유대』 등으로 올라간 지시 랭크(필드에 있는 동안). 올릴 수 없는(랭크 없음) 트레이너는 그대로
  public static string RaisedRank(string rank,int rise){int index=RankIndex(rank);if(index<0||rise<=0)return rank;return RankBands[Math.Min(RankBands.Length-1,index+rise)];}
  public static bool CommandAtLeast(TrainerRecord trainer,string required,int rise,TrainerBattleState state=null){var value=Aptitude(trainer,"지시");return value!=null&&RankAtLeast(RaisedRank(RoleModules.AdjustedRank(value.rank,"지시",state),rise),required);}
  public static int CommandCriticalBonus(TrainerRecord trainer,int rise=0,TrainerBattleState state=null){var value=Aptitude(trainer,"지시");string band=Band(value==null?"":RaisedRank(RoleModules.AdjustedRank(value.rank,"지시",state),rise));return band=="A"?1:band=="AA"?2:band=="AAA"?3:band=="S"?4:0;}
  // 통솔: AA 명중+1, AAA +2, S +3.
  public static int LeadershipAccuracyBonus(TrainerRecord trainer,TrainerBattleState state=null){return TrainerAtLeast(trainer,"통솔","S",state)?3:TrainerAtLeast(trainer,"통솔","AAA",state)?2:TrainerAtLeast(trainer,"통솔","AA",state)?1:0;}
  // 지시 C=숙달, B=전개. 랭크가 비어 있는 트레이너는 기존 데이터 호환을 위해 막지 않는다.
  public static string RequiredOrderRank(string order){string o=order??"";return o.Contains("숙달")?"C":o.Contains("전개")?"B":"";}
  static bool MeetsOrderRank(string order,TrainerRecord trainer,int rise=0,TrainerBattleState state=null){string need=RequiredOrderRank(order);if(need.Length==0||trainer==null)return true;var own=Aptitude(trainer,"지시");string rank=own==null?"":RoleModules.AdjustedRank(own.rank,"지시",state);if(own==null||RankIndex(rank)<0)return true;return RankAtLeast(RaisedRank(rank,rise),need);}
  public static string NormalizeUnlock(string value){string key=(value??"").Trim().ToLowerInvariant();if(key==AimOrders||key.Contains("저격")||key.Contains("회피"))return AimOrders;if(key==SureHitOrder||key.Contains("맞춰라")||key.Contains("필중"))return SureHitOrder;if(key==Pt1||key=="pt1"||key.Contains("pt ①")||key.Contains("pt①")||key.Contains("pt 1"))return Pt1;if(key==Pt2||key=="pt2"||key.Contains("pt ②")||key.Contains("pt②")||key.Contains("pt 2"))return Pt2;return (value??"").Trim();}
  public static string DisplayUnlock(string value){string key=NormalizeUnlock(value);return key==AimOrders?"회피·저격 지령":key==SureHitOrder?"맞춰라 지령":key==Pt1?"PT ①":key==Pt2?"PT ②":value??"";}
  static IEnumerable<string> Unlocks(IEnumerable<PotentialRecord> potentials){return (potentials??Enumerable.Empty<PotentialRecord>()).Where(x=>x!=null&&x.enabled).SelectMany(x=>x.unlocks??new string[0]).Select(NormalizeUnlock).Where(x=>x.Length>0);}
  static IEnumerable<string> Unlocks(IEnumerable<Potential> potentials){return (potentials??Enumerable.Empty<Potential>()).Where(x=>x!=null).SelectMany(x=>x.unlocks??new string[0]).Select(NormalizeUnlock).Where(x=>x.Length>0);}
  public static IEnumerable<string> UnlocksFromTrainer(TrainerRecord trainer){return Unlocks(trainer==null?null:trainer.potentials);}
  public static IEnumerable<string> UnlocksFromActive(IEnumerable<Potential> potentials){return Unlocks(potentials);}
  static bool HasUnlock(string capability,TrainerRecord trainer,TrainerBattleState state,IEnumerable<PotentialRecord> records,IEnumerable<Potential> active){if(state!=null&&(state.UnlockedCapabilities??new HashSet<string>()).Contains(capability))return true;if(Unlocks(trainer==null?null:trainer.potentials).Contains(capability)||Unlocks(records).Contains(capability)||Unlocks(active).Contains(capability))return true;return false;}
  public static bool CanUseOrder(string order,TrainerRecord trainer,TrainerBattleState state=null,IEnumerable<Potential> active=null){int rise=BondModules.CommandRise(active);if(!MeetsOrderRank(order,trainer,rise,state))return false;string capability=RequiredOrderUnlock(order);return capability.Length==0||HasUnlock(capability,trainer,state,null,active)||(trainer!=null&&(capability==AimOrders&&CommandAtLeast(trainer,"A",rise,state)||capability==SureHitOrder&&CommandAtLeast(trainer,"AA",rise,state)));}
  public static bool CanUseForm(string form,TrainerRecord trainer,TrainerBattleState state=null,IEnumerable<Potential> active=null){return !((form??"").Contains("맞춰라"))||HasUnlock(SureHitOrder,trainer,state,null,active)||(trainer!=null&&CommandAtLeast(trainer,"AA",BondModules.CommandRise(active),state));}
  public static string RequiredOrderUnlock(string order){return (order??"").Contains("맞춰라")?SureHitOrder:((order??"").Contains("저격")||(order??"").Contains("회피"))?AimOrders:"";}
  public static bool CanUsePotentialSlot(string slot,TrainerRecord trainer,TrainerBattleState state=null,IEnumerable<PotentialRecord> records=null){if(slot!="PT ①"&&slot!="PT ②")return true;string capability=slot=="PT ①"?Pt1:Pt2;return HasUnlock(capability,trainer,state,records,null)||(trainer!=null&&(capability==Pt1&&(TrainerAtLeast(trainer,"통솔","A",state)||TrainerAtLeast(trainer,"육성","A",state))||capability==Pt2&&TrainerAtLeast(trainer,"통솔","AA",state)));}
  public static bool CanUseRuntimePotentialSlot(string slot,TrainerRecord trainer,TrainerBattleState state,IEnumerable<Potential> active=null){if(slot!="PT ①"&&slot!="PT ②")return true;string capability=slot=="PT ①"?Pt1:Pt2;return HasUnlock(capability,trainer,state,null,active)||(trainer!=null&&(capability==Pt1&&(TrainerAtLeast(trainer,"통솔","A",state)||TrainerAtLeast(trainer,"육성","A",state))||capability==Pt2&&TrainerAtLeast(trainer,"통솔","AA",state)));}
  public static void ApplyTrainerPassives(Fighter fighter,TrainerRecord trainer,TrainerBattleState state,Action<string> log=null){if(fighter==null)return;if(state!=null)state.RefreshUnlocks(fighter.Data==null?null:fighter.Data.potentials);int critical=CommandCriticalBonus(trainer,fighter.OnField&&fighter.HP>0?BondModules.CommandRise(fighter.Data==null?null:fighter.Data.potentials):0,state),accuracy=LeadershipAccuracyBonus(trainer,state);int criticalDelta=critical-fighter.TrainerCriticalStage,accuracyDelta=accuracy-fighter.TrainerAccuracyStage;if(criticalDelta!=0)fighter.CriticalStage=Math.Max(-6,Math.Min(6,fighter.CriticalStage+criticalDelta));if(accuracyDelta!=0)fighter.AccuracyStage=Math.Max(-6,Math.Min(6,fighter.AccuracyStage+accuracyDelta));fighter.TrainerCriticalStage=critical;fighter.TrainerAccuracyStage=accuracy;if(log!=null&&criticalDelta!=0)log(fighter.Data.name+": 트레이너 지시 C +"+critical);if(log!=null&&accuracyDelta!=0)log(fighter.Data.name+": 트레이너 통솔 명중 +"+accuracy);}
  public static string Summary(TrainerRecord trainer){var parts=new List<string>();int c=CommandCriticalBonus(trainer),a=LeadershipAccuracyBonus(trainer);if(c>0)parts.Add("지시 C +"+c);if(a>0)parts.Add("통솔 명중 +"+a);if(TrainerAtLeast(trainer,"통솔","A")||TrainerAtLeast(trainer,"육성","A"))parts.Add("PT ① 사용 가능");if(TrainerAtLeast(trainer,"통솔","AA"))parts.Add("PT ② 사용 가능");return parts.Count==0?"없음":string.Join(" / ",parts);}
  public static void Test(){var trainer=new TrainerRecord();trainer.command.rank="A";if(!CanUseOrder("숙달 저격 지령",trainer)||CanUseOrder("맞춰라！",trainer)||CommandCriticalBonus(trainer)!=1)throw new Exception("Trainer command A access failed");trainer.command.rank="AA";if(!CanUseOrder("숙달 회피 지령",trainer)||!CanUseOrder("맞춰라！",trainer)||CommandCriticalBonus(trainer)!=2)throw new Exception("Trainer command AA access failed");trainer.command.rank="S";if(CommandCriticalBonus(trainer)!=4)throw new Exception("Trainer command S critical bonus failed");trainer.command.rank="D";if(CanUseOrder("숙달 공격 지령",trainer)||!CanUseOrder("공격 지령",trainer))throw new Exception("Mastered order needs command C");trainer.command.rank="C+";if(!CanUseOrder("숙달 공격 지령",trainer)||CanUseOrder("전개 공격 지령",trainer))throw new Exception("Deployed order needs command B");trainer.command.rank="B";if(!CanUseOrder("전개 방어 지령",trainer))throw new Exception("Command B deployed order failed");trainer.command.rank="";if(!CanUseOrder("숙달 공격 지령",trainer))throw new Exception("Unranked trainer order compatibility failed");trainer.leadership.rank="AAA";if(LeadershipAccuracyBonus(trainer)!=2)throw new Exception("Leadership AAA accuracy failed");trainer.leadership.rank="S";if(LeadershipAccuracyBonus(trainer)!=3)throw new Exception("Leadership S accuracy failed");trainer.leadership.rank="A";if(!CanUsePotentialSlot("PT ①",trainer)||CanUsePotentialSlot("PT ②",trainer))throw new Exception("PT 1 aptitude gate failed");trainer.leadership.rank="AA";if(!CanUsePotentialSlot("PT ②",trainer))throw new Exception("PT 2 aptitude gate failed");var state=new TrainerBattleState();state.UnlockedCapabilities.Add(SureHitOrder);trainer.command.rank="";if(!CanUseOrder("맞춰라！",trainer,state)||CanUseOrder("숙달 저격 지령",null)||CanUsePotentialSlot("PT ①",null))throw new Exception("Potential order or no-trainer gate failed");state.UnlockedCapabilities.Add(AimOrders);state.UnlockedCapabilities.Add(Pt1);if(!CanUseOrder("숙달 저격 지령",null,state)||!CanUsePotentialSlot("PT ①",null,state))throw new Exception("Potential unlock extension failed");var fighter=new Fighter(new Pokemon{name="자질 검사",level=100,@base=new[]{100,100,100,100,100,100},iv=new int[6],types=new[]{"노말"},moves=new string[0]});trainer.command.rank="AA";trainer.leadership.rank="AA";ApplyTrainerPassives(fighter,trainer,state);ApplyTrainerPassives(fighter,trainer,state);if(fighter.CriticalStage!=2||fighter.AccuracyStage!=1)throw new Exception("Trainer passive duplication failed");TeamRules.Test();}
 }
}
